package org.freecad.mobilelab;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.*;
import java.util.*;
import org.json.*;
public final class OrganisationRegression {
    static int checks;static File cache;
    interface Action{void run()throws Exception;}
    static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    static void near(double a,double b,double eps){checks++;if(!Double.isFinite(a)||Math.abs(a-b)>eps)throw new AssertionError(a+" expected "+b);}
    static void reject(Action a)throws Exception{checks++;try{a.run();}catch(Exception e){return;}throw new AssertionError("Expected rejection");}
    static int command(String text,int selected)throws Exception{String old=ProjectStore.workspace();NativeCad.beginTransaction(true);try{int id=CommandLine.execute(CommandLine.parse(text),selected);NativeCad.setWorkspace(ProjectStore.workspace());NativeCad.commitTransaction();return id;}catch(Throwable e){NativeCad.rollbackTransaction();ProjectStore.applyWorkspace(old);throw e;}}
    static File csv(String name,String text)throws Exception{File f=new File(cache,name);Files.write(f.toPath(),text.getBytes(StandardCharsets.UTF_8));return f;}
    public static void main(String[] args)throws Exception{
        cache=Files.createTempDirectory("organisation-").toFile();Expressions.reset();Worksheet.reset();Expressions.set("wall","1.6");Worksheet.set("a1","18");Worksheet.set("A2","=A1+2*wall");near(Worksheet.value("A2"),21.2,1e-9);Worksheet.set("A1","20");near(Worksheet.value("A2"),23.2,1e-9);near(Worksheet.formula("=A2+2"),25.2,1e-9);near(Worksheet.formula("=a2+2"),25.2,1e-9);near(Worksheet.formula("=1e3+a1"),1020,1e-9);Worksheet.set("H32","last, \"quoted\"\nline");Worksheet.set("B1","=C1");Worksheet.set("C1","=B1");check(Worksheet.display("B1").startsWith("#ERR"),"Cycles must show an error");reject(()->Worksheet.value("B1"));reject(()->Worksheet.set("I1","1"));reject(()->Worksheet.set("A33","1"));reject(()->Worksheet.set("A0","1"));reject(()->Worksheet.set("A1",String.join("",Collections.nCopies(257,"x"))));
        JSONObject snapshot=Worksheet.json();File out=new File(cache,"out.csv");Worksheet.writeCsv(out);Worksheet.reset();Worksheet.readCsv(out);check(snapshot.toString().equals(Worksheet.json().toString()),"CSV round trip changed raw cells");check(Worksheet.source("H32").equals("last, \"quoted\"\nline"),"Quoted multiline cell lost");near(Worksheet.value("A2"),23.2,1e-9);
        String before=Worksheet.json().toString();for(String bad:new String[]{"\"unclosed","\"ok\"junk","one\"bad","1,2,3,4,5,6,7,8,9",String.join("\n",Collections.nCopies(33,"a"))})reject(()->Worksheet.readCsv(csv("bad.csv",bad)));check(before.equals(Worksheet.json().toString()),"Invalid CSV changed worksheet");Worksheet.readCsv(csv("bom.csv","\ufeff18,=A1+2\r\n"));near(Worksheet.value("B1"),20,0);File invalid=new File(cache,"utf8.csv");Files.write(invalid.toPath(),new byte[]{(byte)0xc3,0x28});reject(()->Worksheet.readCsv(invalid));Worksheet.load(snapshot);reject(()->Worksheet.load(new JSONObject().put("A99","x")));check(snapshot.toString().equals(Worksheet.json().toString()),"Invalid JSON changed worksheet");
        NativeCad.clear();ProjectStore.reset();command("Set wall 1.6",0);command("Cell A1 18",0);command("Cell A2 =A1+2*wall",0);int ring=command("Ring =A1 wall 3",0);near(PrecisionTools.object(ring).getJSONArray("dims").getDouble(0),18,0);command("Cell A1 20",ring);near(Worksheet.value("A2"),23.2,1e-9);check(NativeCad.undo(),"Cell Undo absent");ProjectStore.applyWorkspace(NativeCad.getWorkspace());near(Worksheet.value("A1"),18,0);check(NativeCad.redo(),"Cell Redo absent");ProjectStore.applyWorkspace(NativeCad.getWorkspace());near(Worksheet.value("A1"),20,0);
        File project=new File(cache,"sheet.fcml");ProjectStore.save(project,cache);NativeCad.clear();ProjectStore.reset();NativeCad.beginTransaction(false);try{ProjectStore.restore(project,cache);NativeCad.commitTransaction();}catch(Throwable e){NativeCad.rollbackTransaction();throw e;}near(Worksheet.value("A2"),23.2,1e-9);near(Expressions.evaluate("wall"),1.6,0);command("Cell A1 \"\"",0);check(Worksheet.source("A1").isEmpty(),"Empty quoted cell did not clear");check(NativeCad.undo(),"Cell clear Undo absent");ProjectStore.applyWorkspace(NativeCad.getWorkspace());near(Worksheet.value("A1"),20,0);command("SheetClear",0);check(Worksheet.json().length()==0,"Clear failed");check(NativeCad.undo(),"SheetClear Undo absent");ProjectStore.applyWorkspace(NativeCad.getWorkspace());near(Worksheet.value("A2"),23.2,1e-9);
        NativeCad.clear();ProjectStore.reset();int source=command("Box 2 4 6",0),target=command("Box 4 6 8",0);command("Move 20 30 40",target);double volume=PrecisionTools.object(source).getDouble("volume");command("Align "+target+" X Min Max",source);near(PrecisionTools.object(source).getJSONArray("bbox").getDouble(0),22,1e-7);command("Align "+target+" Y Centre",source);near(PrecisionTools.centre(PrecisionTools.object(source))[1],30,1e-7);command("Align "+target+" Z Max",source);near(PrecisionTools.object(source).getJSONArray("bbox").getDouble(5),48,1e-7);near(PrecisionTools.object(source).getDouble("volume"),volume,1e-7);String scene=NativeCad.objects();reject(()->command("Align "+source+" X Centre",source));reject(()->command("Align "+target+" Q Centre",source));reject(()->command("Align "+target+" X Invalid",source));check(scene.equals(NativeCad.objects()),"Bad align changed scene");
        command("Layer \"Settings A\"",source);command("Layer \"Settings A\"",target);command("LayerHide \"Settings A\"",source);check(!PrecisionTools.object(source).getBoolean("visible")&&!PrecisionTools.object(target).getBoolean("visible"),"Layer hide incomplete");check(NativeCad.undo(),"Layer Undo absent");ProjectStore.applyWorkspace(NativeCad.getWorkspace());check(PrecisionTools.object(source).getBoolean("visible")&&PrecisionTools.object(target).getBoolean("visible"),"Layer Undo incomplete");command("LayerLock \"Settings A\"",source);check(PrecisionTools.object(source).getBoolean("locked")&&PrecisionTools.object(target).getBoolean("locked"),"Layer lock incomplete");reject(()->command("Move 0 0 0",source));command("LayerUnlock \"Settings A\"",source);command("LayerShow \"Settings A\"",source);check(LayerTools.names(new JSONArray(NativeCad.objects())).length==1,"Layer names duplicate");reject(()->command("LayerHide Missing",source));
        NativeCad.clear();ProjectStore.reset();int profile=command("Rectangle 2 3",0),pad=command("Extrude 4",profile);reject(()->command("Align "+pad+" Z Min",profile));
        NativeCad.clear();ProjectStore.reset();int left=command("Box 4 4 4",0),right=command("Box 4 4 4",0);command("Move 120 0 0",right);MeshFrame all=new MeshFrame(NativeCad.meshAtDetail(right,50000),NativeCad.lines(right),NativeCad.surfaceValues());JSONObject rightObject=PrecisionTools.object(right);JSONArray b=rightObject.getJSONArray("bbox");double[] bounds=new double[6];for(int i=0;i<6;i++)bounds[i]=b.getDouble(i);MeshFrame focus=MeshFrame.focus(all,bounds);near(focus.x,120,1e-6);near(focus.y,0,1e-6);near(focus.z,2,1e-6);check(focus.values==all.values&&focus.lines==all.lines&&focus.materials==all.materials,"Focus duplicated geometry");check(focus.radius<all.radius/5,"Focus did not zoom to selection");double[] ray=CameraMath.ray(focus,320,240,0,0,1,0,0,true,160,120);check(NativeCad.pick(ray)==right,"Focused ray selected wrong geometry");SoftwareRasterizer.Image image=SoftwareRasterizer.render(focus,320,240,0,0,1,0,0,true);int pixels=0;for(int pixel:image.pixels)if(pixel!=SoftwareRasterizer.BACKGROUND)pixels++;check(pixels>100,"Focused image empty");reject(()->MeshFrame.focus(all,new double[]{2,0,0,1,0,0}));
        check(CommandLine.parse("Align").ui(),"Align dialog routing");check(CommandLine.parse("Spreadsheet").ui(),"Spreadsheet routing");check(CommandLine.parse("FitSelected").ui(),"FitSelected routing");ArchiveIO.deleteTree(cache);System.out.println("PASS: "+checks+" organisation assertions (worksheet formulas/CSV/errors/persistence/Undo, bounds alignment, layer lock/visibility, focus picking/rendering)");
    }
}
